import {clientCriteria,validSelection,clientResult,rankClients} from './client-trial-model.mjs';
export function createClientTrial({getData,changed,esc,toast}){
 let editingId=null,choosing=false,picks=null,exporting=false;
 const current=()=>getData();
 const byId=id=>clientCriteria.find(c=>c.id===id);
 const button=(text,action,extra='')=>`<button type="button" class="secondary" data-ct="${action}" ${extra}>${text}</button>`;
 const category=result=>result.complete?`<span class="ct-grade ct-grade-${result.category}">${result.category}</span>`:'<span class="pill">Needs review</span>';
 function selection(){const data=current(),selected=picks??data.selected;return `<section class="ct-section"><div class="panel-head"><div><h3>1. Choose your top 10</h3><p>Select the same criteria for every client in this list.</p></div><strong id="ct-count" aria-live="polite">${selected.length} / 10 selected</strong></div><div class="ct-criteria">${clientCriteria.map(c=>`<label class="ct-choice"><input type="checkbox" data-ct-criterion="${c.id}" ${selected.includes(c.id)?'checked':''}><span><strong>${esc(c.label)}</strong><small>${esc(c.help)}</small></span></label>`).join('')}</div><div class="actions">${button('Use these 10 criteria','apply',selected.length===10?'':'disabled')}${data.selected.length?button('Cancel changes','cancel-criteria'):''}</div><p class="panel-note">Changing criteria recalculates every client against the new selection. Existing scores are retained by criterion; newly selected criteria without a score move that client to Needs review. Agree definitions and avoid double-counting similar commercial factors.</p></section>`;}
 function resultText(c){const r=clientResult(c,current().selected);return r.complete?`${r.total}/100 · ${r.total}% · Category ${r.category}`:`${r.scored}/10 scored · ${r.reason}`;}
 function editor(){const data=current(),c=data.clients.find(c=>c.id===editingId);if(!c)return '';return `<section class="ct-section ct-editor"><div class="panel-head"><h3>2. Score the client</h3>${button('Close assessment','close')}</div><div class="project-form"><label>Client label (use an alias)<input data-ct-field="name" maxlength="120" value="${esc(c.name)}" autocomplete="off"></label><label>Reviewer / responsible role<input data-ct-field="reviewer" maxlength="120" value="${esc(c.reviewer||'')}" autocomplete="off"></label></div><div class="notice">Use whole numbers: 0 = does not meet the criterion, 5 = partly meets it, 10 = fully meets it. Leave unknown information blank. All 10 criteria have equal weight. These are staff assessments, not AI-generated ratings.</div><div class="ct-score-rows">${data.selected.map((id,i)=>{const criterion=byId(id);return `<div class="ct-score-row"><div><strong>${i+1}. ${esc(criterion.label)}</strong><small>${esc(criterion.help)}</small></div><label>Score / 10<select data-ct-score="${id}"><option value="">Unknown</option>${Array.from({length:11},(_,n)=>`<option value="${n}" ${c.scores[id]===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Evidence / reason (optional)<input data-ct-evidence="${id}" maxlength="1000" value="${esc(c.evidence[id]||'')}" placeholder="Sanitised reference or explanation"></label></div>`;}).join('')}</div><label class="ct-next">Next action<textarea data-ct-field="next" maxlength="2000" rows="2" placeholder="What should the team do next?">${esc(c.next||'')}</textarea></label><div class="ct-editor-footer"><strong id="ct-editor-result" aria-live="polite">${resultText(c)}</strong>${button('View priority list','show-priority')}</div><small>Changes update the list in this tab immediately. Download the worksheet above to retain assessments after closing or refreshing.</small></section>`;}
 function priority(){const rows=rankClients(current()),ranked=rows.filter(r=>r.complete),pending=rows.filter(r=>!r.complete);return `<div class="ct-summary">${['A','B','C'].map(cat=>`<div><span class="ct-grade ct-grade-${cat}">${cat}</span><strong>${ranked.filter(r=>r.category===cat).length}</strong><small>${{A:'80–100%',B:'60–79%',C:'Below 60%'}[cat]}</small></div>`).join('')}<div><span class="pill">Needs review</span><strong>${pending.length}</strong><small>Not ranked</small></div></div>${ranked.length?`<div class="table-wrap"><table><caption class="sr-only">Client priority list, highest score first</caption><thead><tr><th>Priority</th><th>Client</th><th>Score</th><th>Category</th><th>Owner / next action</th><th>Assessment</th></tr></thead><tbody>${ranked.map(r=>`<tr><td>#${r.rank}</td><td><strong>${esc(r.client.name)}</strong></td><td>${r.total}/100<br><small>${r.total}%</small></td><td>${category(r)}</td><td>${esc(r.client.reviewer||'Unassigned')}<small>${esc(r.client.next||'No next action recorded')}</small></td><td>${button('Review / edit','edit',`data-id="${r.client.id}"`)} ${button('Remove','remove',`data-id="${r.client.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="ct-empty">No ranked clients yet. Choose 10 criteria, add a client and complete all 10 scores to build your priority list.</p>'}${pending.length?`<details open class="ct-pending"><summary>Needs review (${pending.length})</summary>${pending.map(r=>`<div class="ct-pending-row"><div><strong>${esc(r.client.name||'Unnamed client')}</strong><small>${esc(r.reason)} · ${r.scored}/10 scored</small></div><div>${button('Continue scoring','edit',`data-id="${r.client.id}"`)} ${button('Remove','remove',`data-id="${r.client.id}"`)}</div></div>`).join('')}</details>`:''}`;}
 function view(){const data=current(),ready=validSelection(data.selected);return `<section id="client-trial" class="panel ct-trial"><div class="panel-head"><div><p class="eyebrow">TRIAL 1 / CLIENT PRIORITISATION</p><h2>Focus on the right client relationships</h2><p>Choose 10 criteria. Score each client. Compare priorities.</p></div><span class="pill blue">Interactive trial</span></div><div class="ct-steps"><span>01 · Select criteria</span><span>02 · Score clients</span><span>03 · Prioritise</span></div>${!ready||choosing?selection():`<details class="ct-selection-summary"><summary>Your 10 selected criteria</summary><ol>${data.selected.map(id=>`<li>${esc(byId(id).label)}</li>`).join('')}</ol>${button('Change criteria','criteria')}</details>`}<div class="actions">${button('+ Add client','add',ready?'':'disabled')}${ready&&!choosing?button('Change criteria','criteria'):''}${button('Export Excel (.xlsx)','excel',ready&&data.clients.length?'':'disabled')}</div>${editor()}<section id="ct-priority" class="ct-section"><div class="panel-head"><div><h3>3. Client priority list</h3><p>Highest total first. Equal scores share the same rank.</p></div></div><div id="ct-priority-content">${priority()}</div></section><details class="ct-rules"><summary>Scoring rules and how to keep your work</summary><p>Each selected criterion scores 0–10. Ten equally weighted scores give a total out of 100 and the same percentage. Category A: 80–100%; B: 60–79%; C: below 60%. These working thresholds resolve the gap at 59% in the supplied slide; confirm them with your team before operational use.</p><p>Incomplete clients are not assigned a category. A low score is a review input, not an instruction to reject a client. There are 20 criteria from the supplied slide, including the separate “Above average payer”, “Pays on time” and “High rates / fees” criteria.</p><p>Export Excel downloads the current priority list, selected scores and evidence, and criteria guide. It is a snapshot: changes in Excel do not recalculate results or sync to this site. Assessments are held in this tab only, included in Download worksheet and restored with Import worksheet. No client information is sent to an AI provider, company system or shared database. Use aliases and sanitised evidence in this public preview.</p></details></section>`;}
 function repaint(){const root=document.querySelector('#client-trial');if(root)root.outerHTML=view();}
 function updateResults(){const node=document.querySelector('#ct-priority-content');if(node)node.innerHTML=priority();const c=current().clients.find(c=>c.id===editingId),result=document.querySelector('#ct-editor-result');if(c&&result)result.textContent=resultText(c);}
 document.addEventListener('input',e=>{const d=e.target.dataset,c=current().clients.find(c=>c.id===editingId);if(!c)return;
  if(d.ctField&&['name','reviewer','next'].includes(d.ctField))c[d.ctField]=e.target.value;
  else if(d.ctEvidence)c.evidence[d.ctEvidence]=e.target.value;
  else return;
  c.updatedAt=new Date().toISOString();changed();updateResults();
 });
 document.addEventListener('change',e=>{const d=e.target.dataset;
  if(d.ctCriterion){picks??=[...current().selected];if(e.target.checked){if(picks.length===10){e.target.checked=false;toast('Choose exactly 10. Deselect one before adding another.');return;}picks.push(d.ctCriterion);}else picks=picks.filter(id=>id!==d.ctCriterion);document.querySelector('#ct-count').textContent=`${picks.length} / 10 selected`;document.querySelector('[data-ct="apply"]').disabled=picks.length!==10;return;}
  if(d.ctScore){const c=current().clients.find(c=>c.id===editingId);if(!c)return;if(e.target.value==='')delete c.scores[d.ctScore];else c.scores[d.ctScore]=Number(e.target.value);c.updatedAt=new Date().toISOString();changed();updateResults();}
 });
 document.addEventListener('click',async e=>{const target=e.target.closest('[data-ct]');if(!target)return;const data=current();switch(target.dataset.ct){
  case 'excel':{
   if(exporting)return;
   if(!validSelection(data.selected)||!data.clients.length){toast('Choose 10 criteria and add a client first.');return;}
   if(choosing){toast('Apply or cancel your criteria changes before exporting.');return;}
   exporting=true;target.disabled=true;target.textContent='Preparing Excel…';
   const snapshot=structuredClone(data),exportedAt=new Date();
   try{
    const {trialExcelBytes}=await import('./client-trial-excel.mjs');
    const bytes=await trialExcelBytes(snapshot,{exportedAt});
    const url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');
    a.href=url;a.download=`prg-client-priorities-${exportedAt.toISOString().slice(0,10)}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);
    toast('Excel report downloaded. It is a snapshot; use Download worksheet to resume editing on the site.');
   }catch{toast('Excel export could not finish. Please try again. Your inputs remain in this tab; Download worksheet can keep a copy.');}
   finally{exporting=false;if(target.isConnected){target.disabled=false;target.textContent='Export Excel (.xlsx)';}}
   break;
  }
  case 'criteria':choosing=true;picks=[...data.selected];repaint();break;
  case 'cancel-criteria':choosing=false;picks=null;repaint();break;
  case 'apply':if(!validSelection(picks??data.selected)){toast('Select exactly 10 different criteria.');return;}data.selected=[...(picks??data.selected)];choosing=false;picks=null;changed();repaint();toast('Criteria applied to every client. Missing scores stay unranked.');break;
  case 'add':if(!validSelection(data.selected))return;if(data.clients.length>=100){toast('This worksheet supports up to 100 clients. Start another worksheet for a new cohort.');return;}editingId=crypto.randomUUID();data.clients.push({id:editingId,name:`Client ${data.clients.length+1}`,reviewer:'',next:'',scores:{},evidence:{},updatedAt:new Date().toISOString()});changed();repaint();document.querySelector('[data-ct-field="name"]').focus();break;
  case 'edit':editingId=target.dataset.id;repaint();document.querySelector('.ct-editor')?.scrollIntoView({behavior:'smooth',block:'start'});break;
  case 'close':editingId=null;repaint();break;
  case 'show-priority':document.querySelector('#ct-priority').scrollIntoView({behavior:'smooth',block:'start'});break;
  case 'remove':if(!window.confirm('Remove this client assessment from this worksheet? A previously downloaded copy will still contain it.'))return;data.clients=data.clients.filter(c=>c.id!==target.dataset.id);if(editingId===target.dataset.id)editingId=null;changed();repaint();break;
 }});
 return {view,reset(){editingId=null;choosing=false;picks=null;}};
}
